From 968c82b9160c87aa8714d1e451aaf0131bcddf96 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:32:59 +0100
Subject: [PATCH] applets/notes: Apply formatting to the next typed text
 without a selection

Without a selection, the formatting buttons changed the word under the
cursor and could not be turned off after a space or in an empty note. Now
they set the format for the text typed next, and only change a selection.

BUG: 526478
---
 applets/notes/documenthandler.cpp | 60 ++++++++++++++++++++++++-------
 applets/notes/documenthandler.h   |  7 +++-
 2 files changed, 54 insertions(+), 13 deletions(-)

diff --git a/applets/notes/documenthandler.cpp b/applets/notes/documenthandler.cpp
index 63007ea17..3355fb441 100644
--- a/applets/notes/documenthandler.cpp
+++ b/applets/notes/documenthandler.cpp
@@ -31,6 +31,8 @@ DocumentHandler::DocumentHandler()
     , m_cursorPosition(-1)
     , m_selectionStart(0)
     , m_selectionEnd(0)
+    , m_pendingPosition(-1)
+    , m_pendingCharacterCount(0)
 {
 }

@@ -110,11 +112,33 @@ void DocumentHandler::setCursorPosition(int position)
         return;
     }

+    applyPendingFormat(position);
     m_cursorPosition = position;

     reset();
 }

+void DocumentHandler::applyPendingFormat(int position)
+{
+    if (m_pendingPosition < 0 || !m_doc) {
+        return;
+    }
+
+    // Only format what was just typed at the pending position, not text the cursor moved over
+    const int inserted = m_doc->characterCount() - m_pendingCharacterCount;
+    if (inserted > 0 && position == m_pendingPosition + inserted) {
+        QTextCursor cursor(m_doc);
+        cursor.setPosition(m_pendingPosition);
+        cursor.setPosition(position, QTextCursor::KeepAnchor);
+        cursor.joinPreviousEditBlock();
+        cursor.mergeCharFormat(m_pendingFormat);
+        cursor.endEditBlock();
+    }
+
+    m_pendingFormat = QTextCharFormat();
+    m_pendingPosition = -1;
+}
+
 void DocumentHandler::reset()
 {
     Q_EMIT fontFamilyChanged();
@@ -147,17 +171,29 @@ QTextCharFormat DocumentHandler::currentCharFormat() const
     QTextCursor cursor = textCursor();
     if (cursor.hasSelection()) {
         cursor.setPosition(cursor.selectionStart() + 1);
+        return cursor.charFormat();
+    }
+    QTextCharFormat format = cursor.charFormat();
+    if (m_pendingPosition == m_cursorPosition) {
+        format.merge(m_pendingFormat);
     }
-    return cursor.charFormat();
+    return format;
 }

-void DocumentHandler::mergeFormatOnWordOrSelection(const QTextCharFormat &format)
+void DocumentHandler::mergeFormatOnSelectionOrNextText(const QTextCharFormat &format)
 {
     QTextCursor cursor = textCursor();
-    if (!cursor.hasSelection()) {
-        cursor.select(QTextCursor::WordUnderCursor);
+    if (cursor.hasSelection()) {
+        cursor.mergeCharFormat(format);
+        return;
+    }
+    // Without a selection, the format applies to what is typed next
+    if (m_pendingPosition != m_cursorPosition) {
+        m_pendingFormat = QTextCharFormat();
+        m_pendingPosition = m_cursorPosition;
     }
-    cursor.mergeCharFormat(format);
+    m_pendingFormat.merge(format);
+    m_pendingCharacterCount = m_doc ? m_doc->characterCount() : 0;
 }

 void DocumentHandler::setSelectionStart(int position)
@@ -230,7 +266,7 @@ void DocumentHandler::setBold(bool arg)
 {
     QTextCharFormat fmt;
     fmt.setFontWeight(arg ? QFont::Bold : QFont::Normal);
-    mergeFormatOnWordOrSelection(fmt);
+    mergeFormatOnSelectionOrNextText(fmt);
     Q_EMIT boldChanged();
 }

@@ -238,7 +274,7 @@ void DocumentHandler::setItalic(bool arg)
 {
     QTextCharFormat fmt;
     fmt.setFontItalic(arg);
-    mergeFormatOnWordOrSelection(fmt);
+    mergeFormatOnSelectionOrNextText(fmt);
     Q_EMIT italicChanged();
 }

@@ -246,7 +282,7 @@ void DocumentHandler::setUnderline(bool arg)
 {
     QTextCharFormat fmt;
     fmt.setFontUnderline(arg);
-    mergeFormatOnWordOrSelection(fmt);
+    mergeFormatOnSelectionOrNextText(fmt);
     Q_EMIT underlineChanged();
 }

@@ -254,7 +290,7 @@ void DocumentHandler::setStrikeOut(bool arg)
 {
     QTextCharFormat fmt;
     fmt.setFontStrikeOut(arg);
-    mergeFormatOnWordOrSelection(fmt);
+    mergeFormatOnSelectionOrNextText(fmt);
     Q_EMIT strikeOutChanged();
 }

@@ -276,7 +312,7 @@ void DocumentHandler::setFontSize(int arg)
     }
     QTextCharFormat format;
     format.setFontPointSize(arg);
-    mergeFormatOnWordOrSelection(format);
+    mergeFormatOnSelectionOrNextText(format);
     // Also set the block char format, otherwise the old block font will stay and
     // end up taking effect if the user deletes all the text.
     cursor.mergeBlockCharFormat(format);
@@ -319,7 +355,7 @@ void DocumentHandler::setTextColor(const QColor &c)
     }
     QTextCharFormat format;
     format.setForeground(QBrush(c));
-    mergeFormatOnWordOrSelection(format);
+    mergeFormatOnSelectionOrNextText(format);
     Q_EMIT textColorChanged();
 }

@@ -341,7 +377,7 @@ void DocumentHandler::setFontFamily(const QString &arg)
     }
     QTextCharFormat format;
     format.setFontFamilies({arg});
-    mergeFormatOnWordOrSelection(format);
+    mergeFormatOnSelectionOrNextText(format);
     Q_EMIT fontFamilyChanged();
 }

diff --git a/applets/notes/documenthandler.h b/applets/notes/documenthandler.h
index 7b396f9cc..7b8eeb661 100644
--- a/applets/notes/documenthandler.h
+++ b/applets/notes/documenthandler.h
@@ -138,7 +138,8 @@ Q_SIGNALS:
 private:
     QTextCursor textCursor() const;
     QTextCharFormat currentCharFormat() const;
-    void mergeFormatOnWordOrSelection(const QTextCharFormat &format);
+    void mergeFormatOnSelectionOrNextText(const QTextCharFormat &format);
+    void applyPendingFormat(int position);

     QQuickItem *m_target;
     QTextDocument *m_doc;
@@ -147,6 +148,10 @@ private:
     int m_selectionStart;
     int m_selectionEnd;

+    QTextCharFormat m_pendingFormat;
+    int m_pendingPosition;
+    int m_pendingCharacterCount;
+
     QFont m_font;
     int m_fontSize;
     QString m_text;
-- 
